const zlib=require('node:zlib');
const runner=require('../check.cjs'),c=require('../content.cjs'),foundation=require('./data-foundation.cjs');
const {ROOT,inside,bytes,document,write,hash,need}=c,BASE='src/godot-game/';
const EN=BASE+'content/text/en.json',EXPANDED=BASE+'content/text/expanded.json',PACK=BASE+'content/packs/text-data.json',DOC='docs/content/fields.md';
function jsonFiles(directory){return fs.readdirSync(inside(ROOT,directory),{withFileTypes:true}).flatMap(x=>x.isDirectory()?jsonFiles(directory+'/'+x.name):x.name.endsWith('.json')?[directory+'/'+x.name]:[]).sort();}
function sources(){return [...jsonFiles(BASE+'content/config'),...jsonFiles(BASE+'content/ui'),...jsonFiles(BASE+'content/schema'),BASE+'content/audio/events.json',BASE+'content/world/map.json'];}
function fingerprint(files){return files.map(file=>({file,sha256:hash(bytes(ROOT,file))}));}
function pointer(value,p){for(const key of p.split('/').slice(1))value=value[key.replaceAll('~1','/').replaceAll('~0','~')];return value;}
function walk(value,visit,p=''){visit(value,p);if(value&&typeof value==='object')for(const [k,v]of Object.entries(value))walk(v,visit,p+'/'+k.replaceAll('~','~0').replaceAll('/','~1'));}
function fields(){const out=[];for(const file of jsonFiles(BASE+'content/schema'))for(const item of document(ROOT,file).files)for(const field of item.fields)out.push({file:item.path,...field});
 for(const file of jsonFiles(BASE+'content/config')){const data=document(ROOT,file);if(data.fieldDocumentation)for(const item of data.fieldDocumentation.files)for(const field of item.fields)out.push({file:item.path,...field});}
 return out;}
function textSources(){const rows=[];for(const file of sources().filter(x=>!x.includes('/schema/')))walk(document(ROOT,file),(v,p)=>{if(typeof v==='string'&&!p.includes('/fieldDocumentation/')&&/(?:name|label|title|text|reason|warning|message|description|purpose|notice|context|help)$/i.test(p)&&v.length>0)rows.push({file,path:p,text:v});});return rows;}
