const TYPES={day:'integer',player:'player-id',item:'item-id',cost:'nonnegative-number',target:'content-id',count:'integer',completed:'integer',version:'integer',id:'content-id',path:'resource-path',file:'resource-path',field:'json-pointer',value:'display-value',reason:'text',action:'text',binding:'current-binding',warning:'text'};
function placeholders(text){return [...new Set([...text.matchAll(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g)].map(x=>x[1]))].sort();}
function catalogRows(){const rows=Object.entries(COPY).map(([id,text])=>({id,text,placeholders:Object.fromEntries(placeholders(text).map(x=>[x,TYPES[x]])),sources:[{file:'.planning/phases/04-asset-production/04-UI-SPEC.md',path:'Copywriting Contract'}]}));
 const known=new Map(rows.map(x=>[x.text,x]));for(const source of textSources()){let row=known.get(source.text);if(!row){row={id:'source.'+hash(Buffer.from(source.text)).slice(0,20),text:source.text,placeholders:{},sources:[]};rows.push(row);known.set(source.text,row);}row.sources.push({file:source.file,path:source.path});}
 const items=document(ROOT,BASE+'content/config/items.json').definitions,roster=foundation.roster(fs.readFileSync(inside(ROOT,'specs/0.1/initial-spec.md'),'utf8'));
 for(const item of items)for(const key of ['name','description'])rows.push({id:item[key+'Key'],text:key==='name'?item.name:roster.find(x=>x.id===item.id).purpose,placeholders:{},sources:[{file:BASE+'content/config/items.json',path:'/definitions/'+items.indexOf(item)+'/'+key+'Key'},{file:'specs/0.1/initial-spec.md',path:'5.3/'+item.id}]});
 for(const [i,tier]of document(ROOT,BASE+'content/config/structures.json').tiers.entries())rows.push({id:'structure.'+tier.structureId+'.name',text:tier.appearance,placeholders:{},sources:[{file:BASE+'content/config/structures.json',path:'/tiers/'+i+'/appearance'}]});
 for(const row of rows){if(row.id.startsWith('count.')){row.plural={zero:row.text,one:row.text.replace(/results|items|players|days|seconds/g,x=>x.slice(0,-1)),other:row.text};}}
 const bindings=document(ROOT,BASE+'content/config/local-preferences.json').bindings;for(const b of bindings)rows.push({id:'binding.'+b.action,text:'{binding} — '+b.action.replaceAll('-',' '),placeholders:{binding:'current-binding'},bindingRef:b.action,sources:[{file:BASE+'content/config/local-preferences.json',path:'/bindings/'+bindings.indexOf(b)}]});
 return rows.sort((a,b)=>a.id<b.id?-1:1);}
function cell(v){return JSON.stringify(v).replaceAll('|','&#124;').replaceAll('\n','\\n');}
function fieldRow(f){const value=f.default&&typeof f.default==='object'?'children below; exact container SHA256 '+hash(Buffer.from(JSON.stringify(f.default))):cell(f.default);return '| `'+f.path+'` | '+f.type+' | '+f.meaning+' | '+f.unit+' | '+value+' | '+cell(f.allowed)+' | '+cell(f.dependencies)+' | '+cell(f.source)+' |';}
function docs({index,delivery}={}){const all=fields(),lines=['# Authored content field reference','','This document is packaged verbatim inside content/packs/text-data.json as documentation.gzipBase64. The source SHA256 and exact source path are retained. Runtime inspection reads the packaged bytes; it does not require repository or donor access. Content integration and portable export adoption remain owned by Plans 23/31.','','## Editing and authority','','Host balance is authoritative for a run. DT-25 display/audio/bindings are player-local and never override host balance. Defaults below are proposed balance, not playtest certification. Every container default is the exact ordered union of its child rows; its SHA256 authenticates the full canonical JSON value. No omitted field has a hidden fallback. Paths are exact JSON pointers; units, bounds, dependencies and source evidence are copied from the actual field schemas. Metadata source snapshots are evidence, not another balance authority.','','## Representative edits','','- Item: content/config/items.json /definitions/0/weightKilograms changes IT-01 Money from 0.001 to 0.002 kg/item; preserve stable ID and canonical image/text references. Validate with data.items-combat.','- Cost: content/config/structures.json /tiers/1/price changes main tier2 price from200 to220 crowns; keep fullValuation and repairFee consistent with the chosen designer valuation. Repair valuation remains independently documented as 50% of the full tier cost; never bill proportional missing health. Validate with data.map-structures and ui.camp.','- Zombie: content/config/zombies.json /archetypes/0/health changes Shambler health from65 to70; this changes only that archetype; keep loot/content references. Validate with data.zombies.','- Independent progression: content/config/zombie-progression.json /stages/0/regularPerPortal changes stage0 regular wave count from6 to7 independently of the archetypes file; preserve stage order, six portal relationships, positive counts and unchanged living zombie stats. Validate with data.zombies and data.campaign.','- Sound: content/audio/events.json event bindings retain their AU IDs and exact current sample/bank IDs; change /events/0/routes/0/gainLinear (footstep.walk) from0.85 to0.75 linear amplitude, a finite nonnegative number, never invent a path or use a donor absolute locator at runtime. Validate audio lifecycle and held-out cases.','- Map: content/config/map-sites.json /portals/0/x changes left.portal.1 from-100 to-102 world units, synchronizing its content/world/map.json position and ordering; retain six authored locations and references to content/world/map.json; edit a coordinate with strict path/site/edge validation and no procedural generation. Validate data.map-structures and world.inspector.','','## Baseline field inventory',''];
 for(const file of [...new Set(all.map(x=>x.file))]){lines.push('### '+file,'','Scope: '+(file.endsWith('/local-preferences.json')?'player-local preferences':'host balance / shared authored definitions'),'', '| JSON pointer | Type | Meaning | Unit | Shipped default | Allowed | Dependencies | Source |','| --- | --- | --- | --- | --- | --- | --- | --- |');for(const f of all.filter(x=>x.file===file))lines.push(fieldRow(f));lines.push('');}
 lines.push('## Support schema inventory','','Each row identifies a structural field in the actual support resource. Array indices are represented by *; each current scalar value is retained in the authenticated source and native read-only inspector. These are resource/schema constraints, not shared gameplay balance defaults. Payload byte arrays/base64 are content, not editable numeric balance fields.','');
 for(const file of jsonFiles(BASE+'content').filter(x=>!x.includes('/config/')&&!x.includes('/schema/')&&!x.includes('/text/')&&!x.endsWith('/packs/text-data.json')&&!x.includes('/compatibility/')&&!x.endsWith('/packs/compatibility.json'))){const publication=[BASE+'content/pack-index.json',BASE+'content/packs/delivery.json'].includes(file),seen=new Map();walk(file===BASE+'content/pack-index.json'&&index?index:file===BASE+'content/packs/delivery.json'&&delivery?delivery:document(ROOT,file),(v,p)=>{const shape=p.replace(/\/\d+(?=\/|$)/g,'/*');if(!seen.has(shape))seen.set(shape,{type:v===null?'null':Array.isArray(v)?'array':typeof v,value:v});});lines.push('### '+file,'',publication?'Publication instance: actual bytes, paths, hashes, versions and obligations are independently authenticated by the content census and publisher. Field shapes/types are documented here; dynamic publication values do not participate in the documentation payload identity.':'Source SHA256: `'+hash(bytes(ROOT,file))+'`. Root field dependencies: stable IDs, packaged project paths and current content version; no network/donor dependency.','','| Field shape | Type | Default/example and allowed representation |','| --- | --- | --- |');for(const [p,x]of seen){const v=publication?'Current publication value; validate with content census/publication':x.value&&typeof x.value==='object'?'complete children below':cell(x.value);lines.push('| `'+p+'` | '+x.type+' | '+(v.length>200?v.slice(0,200)+' (full value in authenticated source)':v)+' |');}lines.push('');}
 lines.push('## Text schema and DT-18','','TXT-01 is English; rows have stable id, text, typed placeholders, optional zero/one/other plural forms, exact source bindings and optional bindingRef. Counts are nonnegative integers. Current bindings come from DT-25 by action identity, never fixed key art. TXT-02 is replacement test data, not an additional shipped locale; placeholders and IDs are identical and every label has at least twice its original length. Accented names, multiline errors, long unbroken identities and unsupported glyph diagnostics are explicit. A missing glyph remains an unavailable diagnostic even when a fallback renders another glyph.','','DT-18 points to this entire field inventory, catalog and independently editable DT-14. Text/data pack schemaVersion and version are positive stable integers. documentation includes sourcePath, sha256, encoding UTF-8 and full text. bindings list exact packaged paths and hashes. No actual save transaction or gameplay editor is supplied.','','## Packaging and compatibility','','Include content/packs/text-data.json, both text resources and their declared bindings explicitly in the portable content closure; documentation.gzipBase64 is the bundled copy of this file. TXT-02 is an inspection replacement fixture, never an advertised locale. DT-24 compatibility is metadata only: IDs, versions, saved geometry, equipment, exploration, ruins, paid work, queues and current loops; there are no duplicated image/audio payloads. Plans 23/31 retain final index/export reconciliation.','');return lines.join('\n');}
function authorWrite(file,value){need([EN,EXPANDED,PACK,DOC].includes(file),'AUTHOR_SCOPE');fs.mkdirSync(path.dirname(inside(ROOT,file)),{recursive:true});fs.writeFileSync(inside(ROOT,file),Buffer.isBuffer(value)?value:JSON.stringify(value,null,2)+'\n');}
function author(){const rows=catalogRows();const en={schemaVersion:1,id:'TXT-01',version:1,locale:'en',rows};authorWrite(EN,en);authorWrite(EXPANDED,{schemaVersion:1,id:'TXT-02',version:1,testReplacementOnly:true,shippedLocale:false,rows:rows.map(x=>({...x,text:x.text+' — Extended inspection label: '+x.text, ...(x.plural?{plural:Object.fromEntries(Object.entries(x.plural).map(([k,v])=>[k,v+' — Extended inspection label: '+v]))}:{})})),fixtures:{accentedNames:['Élodie','Jérôme','İpek','Zoë'],multiline:'Cannot load resource.\nRestore the exact definition, then choose Recheck resources.',longId:'content/'+('long-identity-'.repeat(24))+'definition.json',unsupportedGlyph:'\u0378',glyphStatus:'Unavailable — unsupported glyph U+0378'}});const text=docs();authorWrite(DOC,Buffer.from(text));authorWrite(PACK,{schemaVersion:1,id:'text-data',version:1,obligations:['TXT-01','TXT-02','DT-18'],acceptance:'pending-04-32',documentation:{sourcePath:DOC,encoding:'UTF-8+gzip/base64',sha256:hash(Buffer.from(text)),uncompressedBytes:Buffer.byteLength(text),gzipBase64:zlib.gzipSync(Buffer.from(text),{level:9}).toString('base64')},bindings:[EN,EXPANDED,...sources()].map(file=>({path:file.slice(BASE.length),sha256:hash(bytes(ROOT,file))}))});}
function unpackDocumentation(pack){return zlib.gunzipSync(Buffer.from(pack.documentation.gzipBase64,'base64'),{maxOutputLength:16777216}).toString('utf8');}
function authorDocumentation(){const before=fingerprint([EN,EXPANDED]),text=docs(),pack=document(ROOT,PACK);
 pack.documentation={sourcePath:DOC,encoding:'UTF-8+gzip/base64',sha256:hash(Buffer.from(text)),uncompressedBytes:Buffer.byteLength(text),gzipBase64:zlib.gzipSync(Buffer.from(text),{level:9}).toString('base64')};
 pack.bindings=[EN,EXPANDED,...sources()].map(file=>({path:file.slice(BASE.length),sha256:hash(bytes(ROOT,file))}));
 authorWrite(DOC,Buffer.from(text));authorWrite(PACK,pack);need(equal(before,fingerprint([EN,EXPANDED])),'TEXT_CATALOG_MUTATED');}
function documentationControls(en,expanded,pack){const controls=[],index=document(ROOT,c.INDEX),changed=structuredClone(index),original=docs({index});
 changed.version+=1;if(changed.model==='completed-shards-v1')changed.files.find(x=>x.id===changed.outputs[0].file).sha256='0'.repeat(64);else changed.outputs[0].sha256='0'.repeat(64);need(docs({index:changed})===original,'TEXT_PUBLICATION_INSTANCE_CYCLE');
 const invalid=c.validate(ROOT,changed);need(invalid.diagnostics.some(x=>x.code==='OUTPUT_INVALID'&&x.id===changed.outputs[0].id&&x.message.includes('FILE_HASH_MISMATCH')),'TEXT_INDEX_TAMPER_ACCEPTED');
 controls.push({id:'publication-instance-independent-docs',stableDocumentation:true,indexTamperRejected:true});
 const schema=structuredClone(index);schema.schemaVersion='unsupported';need(docs({index:schema})!==original,'TEXT_INDEX_SCHEMA_HIDDEN');
 assert.throws(()=>c.validate(ROOT,schema),/INDEX_INVALID/);controls.push({id:'publication-schema-retained',rejected:true});
 const actual=fields(),field=actual.find(x=>x.type==='number');need(field,'TEXT_CONTROL_NUMERIC_FIELD');field.default+=1;
 assert.throws(()=>fieldUnion(actual),/TEXT_FIELD_DEFAULT/);controls.push({id:'authored-default-independent',rejected:true});
 const rebound=structuredClone(pack);rebound.bindings.find(x=>x.path==='content/config/run.json').sha256='0'.repeat(64);
 assert.throws(()=>validateCatalog(en,expanded,rebound),/TEXT_BINDING_HASH/);controls.push({id:'non-index-source-binding',rejected:true});
 validateCatalog(en,expanded,pack);fieldUnion();need(docs({index})===original,'TEXT_DOC_RESTORATION');
 controls.push({id:'current-text-source-restored-positive',passed:true});return controls;}
function fieldUnion(actual=fields()){const keys=new Set(),documents=new Map(),coverage=[];for(const f of actual){const key=f.file+'#'+f.path;need(!keys.has(key),'TEXT_FIELD_DUPLICATE',key);keys.add(key);if(!documents.has(f.file)){const data=document(ROOT,f.file);delete data.fieldDocumentation;documents.set(f.file,data);}need(equal(pointer(documents.get(f.file),f.path),f.default),'TEXT_FIELD_DEFAULT',key);for(const k of ['meaning','unit','allowed','dependencies','source'])need(Object.hasOwn(f,k),'TEXT_FIELD_METADATA',key+' '+k);}
 for(const [file,data]of documents){let count=0;walk(data,(v,p)=>{need(keys.has(file+'#'+p),'TEXT_FIELD_UNCOVERED',file+'#'+p);count++;});coverage.push({file,fields:count,scope:file.endsWith('/local-preferences.json')?'local':'host'});}need(actual.length===4603&&keys.size===4603,'TEXT_FIELD_UNION');return coverage;}
function validateCatalog(en,expanded,pack){need(en.id==='TXT-01'&&en.locale==='en'&&expanded.id==='TXT-02'&&expanded.testReplacementOnly&&!expanded.shippedLocale,'TEXT_IDENTITY');const expected=catalogRows();need(equal(en.rows,expected),'TEXT_REQUIRED_SOURCE');need(expanded.rows.length===en.rows.length,'TEXT_EXPANDED_COUNT');for(const [i,row]of en.rows.entries()){const other=expanded.rows[i];need(other.id===row.id&&other.text.length>=row.text.length*2&&equal(other.placeholders,row.placeholders),'TEXT_EXPANSION',row.id);need(equal(placeholders(other.text),placeholders(row.text)),'TEXT_PLACEHOLDERS',row.id);if(row.plural)for(const key of ['zero','one','other'])need(other.plural[key].length>=row.plural[key].length*2&&equal(placeholders(other.plural[key]),placeholders(row.plural[key])),'TEXT_PLURAL',row.id);}
 need(pack.documentation.sourcePath===DOC&&unpackDocumentation(pack)===bytes(ROOT,DOC).toString('utf8')&&hash(Buffer.from(unpackDocumentation(pack)))===pack.documentation.sha256,'TEXT_PACKAGED_DOC');need(unpackDocumentation(pack)===docs(),'TEXT_FIELD_DOCUMENTATION');for(const ref of pack.bindings)need(hash(bytes(ROOT,BASE+ref.path))===ref.sha256,'TEXT_BINDING_HASH',ref.path);return {strings:en.rows.length,fields:fields().length,sourceBindings:en.rows.reduce((n,x)=>n+x.sources.length,0),packagedDocumentationBytes:Buffer.byteLength(unpackDocumentation(pack))};}
async function catalog(context){const before=fingerprint([EN,EXPANDED,PACK,DOC,...sources()]);write(context.directory,'inputs.json',before);write(context.directory,'field-union.json',fieldUnion());const en=document(ROOT,EN),ex=document(ROOT,EXPANDED),pack=document(ROOT,PACK),result=validateCatalog(en,ex,pack),controls=[];for(const kind of ['missing-message','placeholder-type','plural','current-binding','expanded-label','packaged-doc']){const a=structuredClone(en),b=structuredClone(ex),p=structuredClone(pack);if(kind==='missing-message')a.rows.pop();if(kind==='placeholder-type')a.rows.find(x=>x.id==='hub.loading').placeholders.id='integer';if(kind==='plural')b.rows.find(x=>x.id==='count.items').plural.one='items';if(kind==='current-binding')a.rows.find(x=>x.bindingRef).bindingRef='missing-action';if(kind==='expanded-label')b.rows[0].text='short';if(kind==='packaged-doc')p.documentation.sha256='bad';assert.throws(()=>validateCatalog(a,b,p));controls.push({id:kind,rejected:true});}controls.push(...documentationControls(en,ex,pack));write(context.directory,'negative-controls.json',controls);write(context.directory,'fields.json',fields());need(equal(before,fingerprint([EN,EXPANDED,PACK,DOC,...sources()])),'TEXT_SOURCE_CHANGED');return {...result,negativeControls:controls.length,scope:'Source/headless text and documentation only; native readability and ASSET acceptance pending04-32'};}
const metadata={group:'text',title:'Complete English catalog typed formatting and packaged designer documentation',importance:'High',rationale:'Missing or mutated text/field defaults makes required content unusable or silently changes authoring authority',needsGameWindow:false,runGroup:'G0-text',order:1,requirements:['ASSET-01','ASSET-02','ASSET-03','ASSET-04'],acceptance:['AC-10','AC-11','AC-13'],setup:'Actual authored definitions and exact English/expanded replacement resources; no game window',actions:['Compare every current source label and required copy with stable catalog messages','Check typed placeholders plurals current-binding actions and twice-length replacements','Authenticate full packaged field documentation and reject independent corrupt controls'],expected:'Every required current text/source binding field default and packaged documentation passes with explicit negative controls',reset:'Read-only source checks; discard detached corrupt subjects',evidence:['inputs.json','negative-controls.json','fields.json','result.json']};
